-- Questões originais de estudo baseadas em Date, tradução da 8ª edição (2004).
-- Não são questões oficiais do CP-T nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens são rascunhos: revise no painel antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve os registros deste lote.
-- As explicações acompanham o contexto histórico da edição, quando pertinente.
-- Capítulo 7: Álgebra relacional — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('d7910369-cd99-5f2d-9504-8b65edced0f6', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Por que o fechamento é importante para expressões relacionais aninhadas?', '["Todas as operações passam a ter custo igual.","Todo resultado se torna automaticamente persistente.","O resultado de uma operação pode servir de entrada a outra.","Impede consultas sobre relações vazias.","Dispensa nomes de atributos."]'::jsonb, 2, 'O fechamento sustenta a composição de operadores relacionais.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.2, páginas 315–317 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2b039bcc-cf96-5f95-ad34-bb675b22f451', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Uma autojunção precisa distinguir dois atributos originalmente homônimos. Qual operador auxilia?', '["COMMIT.","ROLLBACK.","RENAME.","DELETE.","GRANT."]'::jsonb, 2, 'A renomeação evita conflitos e explicita correspondências de atributos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.3, páginas 318–321 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b821485b-e439-532d-ac20-5d10bffc4c1e', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Fácil', 'R={1,2} e S={2,3} são relações unárias compatíveis. Qual é R UNION S?', '["{2}.","{1,2,3}.","{3}.","{1,2,2,3}.","{1}."]'::jsonb, 1, 'A união contém as tuplas presentes em qualquer operando, sem multiplicidade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('50afad9a-9897-511c-b4b7-a1405ef880f0', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'R={1,2} e S={2,3}, com mesmo cabeçalho. Qual é R INTERSECT S?', '["{1}.","{2}.","{1,2,3}.","Vazio.","{3}."]'::jsonb, 1, 'A interseção conserva apenas tuplas presentes nos dois operandos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fd121816-43bb-59e2-83f9-a73df8aa7a66', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Fácil', 'R={1,2} e S={2,3}, com mesmo cabeçalho. Qual é R MINUS S?', '["{2}.","{3}.","{2,3}.","{1,2,3}.","{1}."]'::jsonb, 4, 'A diferença conserva tuplas do primeiro operando ausentes do segundo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a454f649-8f47-57e8-9432-87b6514ce6ff', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'União relacional exige que seus operandos possuam:', '["Cabeçalhos compatíveis segundo as regras de tipagem.","Os mesmos índices.","A mesma localização física.","Uma tupla em comum.","A mesma cardinalidade."]'::jsonb, 0, 'A união precisa produzir uma relação homogênea, preservando o fechamento.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cab5d505-cceb-5cb0-960b-8417dd1b2650', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'R tem três tuplas e S quatro, com atributos disjuntos. R TIMES S terá quantas tuplas?', '["7.","1.","3.","12.","4."]'::jsonb, 3, 'O produto cartesiano combina cada tupla de R com cada tupla de S.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f4f060b6-d958-53b3-8906-fffa04086a28', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Uma restrição sobre R pode aumentar sua cardinalidade?', '["Sim, quando o predicado é falso.","Não, porque remove todos os atributos.","Sim, sempre duplica tuplas aprovadas.","Não; seu corpo é subconjunto do corpo de R.","Sim, se houver índices."]'::jsonb, 3, 'Seleção filtra tuplas sem criar novas combinações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8d2fc26e-9cb4-55ed-9e0b-7f24c8c209ae', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Projetar R sobre menos atributos pode reduzir sua cardinalidade por quê?', '["A projeção acrescenta valores nulos.","Tuplas antes distintas podem produzir a mesma tupla projetada.","O grau deve ser igual à cardinalidade.","Todo atributo removido exclui uma linha.","A projeção ordena fisicamente os registros."]'::jsonb, 1, 'A projeção relacional elimina multiplicidade porque seu resultado é um conjunto.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('768b28d6-40d1-5e2b-b192-7c8463b42a58', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Uma junção natural usa atributos comuns para:', '["Combinar tuplas cujos valores nesses atributos coincidam.","Criar duas cópias de cada atributo comum.","Escolher somente a primeira tupla de cada relação.","Somar automaticamente seus valores.","Remover todos os atributos não comuns."]'::jsonb, 0, 'A correspondência ocorre nos atributos comuns compatíveis.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4b323774-2dfd-50b2-a196-33aec0ab828d', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Uma consulta pede candidatos inscritos em todos os cursos de um conjunto. Qual operador clássico corresponde ao requisito universal?', '["Divisão.","Renomeação.","União.","Restrição sem condição.","Produto sem filtro."]'::jsonb, 0, 'Divisão modela consultas em que se exige associação com todos os elementos de um conjunto.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0b4cd2d1-b953-558e-bda8-3264d8419e51', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Qual operador, em geral, não é comutativo?', '["União.","Produto com atributos disjuntos.","Junção natural.","Diferença.","Interseção."]'::jsonb, 3, 'R MINUS S e S MINUS R podem produzir resultados diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.7, páginas 344–346 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('354bdf7a-fb4d-543f-8159-f804e58c9dd9', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Para relações compatíveis, R UNION R resulta em:', '["Um valor escalar.","Uma relação de grau dobrado.","Uma relação com o dobro das tuplas.","R.","Uma relação vazia."]'::jsonb, 3, 'A união é idempotente no modelo de conjuntos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.7, páginas 344–346 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f34f7a33-ad37-5883-ae6a-7123e9012a22', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Uma semijunção de R com S retorna:', '["Apenas tuplas de S sem correspondência.","Uma contagem escalar sem cabeçalho.","O produto integral sem filtro.","Todos os atributos de R e S obrigatoriamente.","Tuplas de R que encontram correspondência em S, preservando o cabeçalho de R."]'::jsonb, 4, 'A semijunção testa existência de associação sem incorporar os atributos exclusivos de S.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.8, páginas 347–357 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('07f2307e-6319-56d2-a442-3887c3d6a08b', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Para obter entidades de R sem correspondência em S, o operador adicional apropriado é:', '["SEMIMINUS.","RENAME.","SEMIJOIN.","SUMMARIZE.","EXTEND."]'::jsonb, 0, 'A semidiferença conserva as tuplas do primeiro operando que não encontram correspondência.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.8, páginas 347–357 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('adb6631b-303b-5696-83f3-cf9f79f254f0', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Qual operador acrescenta atributos calculados a partir dos existentes?', '["COMMIT.","EXTEND.","RENAME, exclusivamente.","INTERSECT.","MINUS."]'::jsonb, 1, 'EXTEND deriva novos valores e amplia o cabeçalho do resultado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.8, páginas 347–357 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3ada7214-f1cd-5d7f-b28d-bf462b87b441', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Qual operador permite produzir totais por grupos?', '["RENAME.","ROLLBACK.","SUMMARIZE.","MINUS, exclusivamente.","TIMES, exclusivamente."]'::jsonb, 2, 'Totalização calcula agregados para os grupos especificados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.8, páginas 347–357 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('144b9458-ab15-5b0d-b85a-e12e689d6adf', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'A partir de ligações diretas entre cidades, qual operador adicional pode calcular alcançabilidade transitiva?', '["RENAME.","EXTEND sem recursão.","TCLOSE.","UNION de uma relação consigo mesma.","PROJECT sobre um atributo."]'::jsonb, 2, 'O fechamento transitivo inclui ligações obtidas por caminhos de vários passos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.8, páginas 347–357 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c66e9167-c727-57b4-be2f-b7e6421496a3', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'GROUP pode reunir atributos de várias tuplas em:', '["Uma senha compartilhada.","Um novo índice externo.","Uma transação sem commit.","Um ponteiro físico obrigatório.","Um atributo cujo valor é uma relação."]'::jsonb, 4, 'Agrupamento relacional permite construir valores relacionais aninhados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.9, páginas 358–361 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6c4fd3c1-54fb-5124-8eef-4b00fee2a846', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Qual operação faz o movimento inverso ao agrupamento de um atributo relacional?', '["COMMIT.","RENAME.","DROP TYPE.","REVOKE.","UNGROUP."]'::jsonb, 4, 'O desagrupamento expande o conteúdo do atributo relacional para o resultado correspondente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.9, páginas 358–361 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false)
